/**
 * Situation report (SitRep) compiled from Phoenix data alone.
 *
 * Deterministic and offline: every line comes from a field of the event or
 * of the events around it, so each statement can be traced to its source.
 * Nothing here is generated by a language model.
 */

import type { ApiDisasterEvent } from "@/lib/api/client";
import type { Translations } from "@/lib/i18n/types";

export interface SitrepNearby {
  event: Pick<ApiDisasterEvent, "id" | "title" | "severity" | "type">;
  distanceKm: number;
}

export interface SitrepSection {
  id: "summary" | "impact" | "confidence" | "nearby" | "sources" | "next";
  heading: string;
  lines: string[];
}

export interface Sitrep {
  title: string;
  generatedAt: string;
  sections: SitrepSection[];
}

type SitrepEvent = Pick<
  ApiDisasterEvent,
  | "title"
  | "type"
  | "severity"
  | "description"
  | "location"
  | "startDate"
  | "endDate"
  | "isActive"
  | "affectedPopulation"
  | "sources"
  | "trust"
>;

const fill = (template: string, vars: Record<string, string | number>) =>
  template.replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? `{${k}}`));

export interface SitrepDamage {
  total: number;
  destroyed: number;
  damaged: number;
}

export function buildSitrep(
  event: SitrepEvent,
  nearby: SitrepNearby[],
  t: Translations,
  lang: string,
  now: Date = new Date(),
  damage?: SitrepDamage | null,
): Sitrep {
  const s = t.sitrep;
  const typeLabel =
    (t.sidebar as Record<string, string>)[event.type] ?? event.type;
  const sevLabel =
    (t.sidebar as Record<string, string>)[event.severity] ?? event.severity;
  const date = (iso: string) =>
    new Date(iso).toLocaleString(lang, {
      dateStyle: "medium",
      timeStyle: "short",
      timeZone: "UTC",
    }) + " UTC";
  const place =
    event.location.country ||
    (event.location.lat != null && event.location.lng != null
      ? `${event.location.lat.toFixed(2)}, ${event.location.lng.toFixed(2)}`
      : s.unknownPlace);

  const summary = [
    fill(s.lineWhat, {
      type: typeLabel,
      severity: sevLabel.toLowerCase(),
      place,
    }),
    fill(s.lineWhen, { start: date(event.startDate) }),
    event.isActive
      ? s.lineActive
      : fill(s.lineEnded, { end: event.endDate ? date(event.endDate) : "—" }),
  ];
  if (event.description) summary.push(event.description);

  const impact =
    event.affectedPopulation != null && event.affectedPopulation > 0
      ? [
          fill(s.linePopulation, {
            n: event.affectedPopulation.toLocaleString(lang),
          }),
        ]
      : [s.lineNoPopulation];

  if (damage && damage.total > 0) {
    impact.push(
      fill(t.damage.sitrep, {
        n: damage.total.toLocaleString(lang),
        destroyed: damage.destroyed.toLocaleString(lang),
        damaged: damage.damaged.toLocaleString(lang),
      }),
    );
  }

  const confidence: string[] = [];
  if (event.trust) {
    confidence.push(
      fill(s.lineConfidence, {
        pct: Math.round(event.trust.confidence * 100),
        n: event.trust.sourceCount,
        stage: t.trust.stages[event.trust.lifecycle],
      }),
    );
    if (event.trust.reasons.includes("stale"))
      confidence.push(t.trust.reasons.stale);
  }

  const nearbyLines = nearby.length
    ? nearby.slice(0, 5).map((n) =>
        fill(s.lineNearby, {
          title: n.event.title,
          km: Math.round(n.distanceKm),
          severity: (
            (t.sidebar as Record<string, string>)[n.event.severity] ??
            n.event.severity
          ).toLowerCase(),
        }),
      )
    : [s.lineNoNearby];

  const sources = event.sources.length
    ? event.sources.map((src) => src.name)
    : [s.lineNoSources];

  const next: string[] = [s.nextVerify];
  if (event.trust && event.trust.sourceCount <= 1)
    next.push(s.nextSecondSource);
  if (event.isActive) next.push(s.nextImagery);
  if (nearby.length) next.push(s.nextCompound);

  return {
    title: fill(s.reportTitle, { title: event.title }),
    generatedAt: now.toISOString(),
    sections: [
      { id: "summary", heading: s.summary, lines: summary },
      { id: "impact", heading: s.impact, lines: impact },
      ...(confidence.length
        ? [
            {
              id: "confidence" as const,
              heading: s.confidence,
              lines: confidence,
            },
          ]
        : []),
      { id: "nearby", heading: s.nearby, lines: nearbyLines },
      { id: "sources", heading: s.sources, lines: sources },
      { id: "next", heading: s.next, lines: next },
    ],
  };
}

/** Plain text for pasting into email or chat */
export function sitrepToText(report: Sitrep, t: Translations): string {
  const out = [
    report.title,
    fill(t.sitrep.generated, {
      time: report.generatedAt.slice(0, 16).replace("T", " ") + " UTC",
    }),
    "",
  ];
  for (const section of report.sections) {
    out.push(section.heading);
    for (const line of section.lines) out.push(`- ${line}`);
    out.push("");
  }
  out.push(t.sitrep.disclaimer);
  return out.join("\n");
}
